export function normalizePosts(posts) {
  if (!Array.isArray(posts)) throw new Error('WordPress must return a post array.');
  const ids = new Set();
  return posts.map(post => {
    if (!post || !Number.isSafeInteger(post.id) || post.id < 1 || typeof post.title?.rendered !== 'string') throw new Error('Every WordPress post needs an ID and rendered title.');
    if (ids.has(post.id)) throw new Error('Repeated post IDs were returned; keep the site stable while listing and try again.');
    ids.add(post.id);
    return { id: post.id, title: post.title.rendered };
  });
}

export default function collectPages({ previousState, pagePosts, pagination }) {
  if (previousState === null) {
    if (pagePosts !== null || pagination !== null) throw new Error('Unexpected WordPress page before collection starts.');
    return { state: { posts: [], page: 0 }, nextPage: 1, more: true };
  }
  if (!Array.isArray(previousState.posts) || !Number.isSafeInteger(previousState.page) || previousState.page < 0) throw new Error('Invalid WordPress page collection state.');
  const page = previousState.page + 1, added = normalizePosts(pagePosts), ids = new Set(previousState.posts.map(post => post.id));
  if (added.some(post => ids.has(post.id))) throw new Error('Repeated post IDs were returned; keep the site stable while listing and try again.');
  const posts = [...previousState.posts, ...added], totalPages = pagination?.totalPages;
  if (totalPages !== null && (!Number.isSafeInteger(totalPages) || totalPages < 0 || (totalPages < page && !(page === 1 && posts.length === 0 && totalPages === 0)))) throw new Error('Invalid WordPress page-count metadata.');
  return { state: { posts, page }, nextPage: page + 1, more: totalPages !== null && page < totalPages };
}

