export default function collectPostClassifications({ posts, taxonomy, previousState, category }) {
  if (!Array.isArray(posts) || !Array.isArray(taxonomy) || taxonomy.length === 0) throw new Error('Posts and the validated category taxonomy are required.');
  let state;
  if (previousState === null) {
    if (category !== null) throw new Error('Unexpected classification before processing starts.');
    state = { index: 0, categories: [] };
  } else {
    if (!Number.isSafeInteger(previousState.index) || previousState.index < 0 || previousState.index >= posts.length || !Array.isArray(previousState.categories) || previousState.categories.length !== previousState.index) throw new Error('Invalid WordPress classification state.');
    if (category?.id !== posts[previousState.index].id || !taxonomy.some(item => item.id === category.categoryId)) throw new Error('The classification does not match this post and configured taxonomy.');
    state = { index: previousState.index + 1, categories: [...previousState.categories, category] };
  }
  return { state, index: state.index, more: state.index < posts.length };
}

