export default function trackPostUpdates({ categories, previousState }) {
  if (!Array.isArray(categories)) throw new Error('The complete validated category collection is required.');
  let index = 0;
  if (previousState !== null) {
    if (!Number.isSafeInteger(previousState.index) || previousState.index < 0 || previousState.index >= categories.length) throw new Error('Invalid WordPress update progress.');
    index = previousState.index + 1;
  }
  const category = categories[index];
  return { state: { index }, id: category?.id ?? 1, categoryIds: category ? [category.categoryId] : [], more: index < categories.length, count: index };
}

