export default async function classifyPost({ posts, index, taxonomy }, context) {
  if (!Array.isArray(posts) || !Number.isSafeInteger(index) || index < 0 || index >= posts.length) throw new Error('A selected WordPress post is required.');
  context.signal?.throwIfAborted();
  const category = await context.workflows.call('classify-post', { ...posts[index], taxonomy });
  return { category };
}

